import re
import pytest
from hypothesis import given, example
import hypothesis.strategies as st

from roman import to_roman, from_roman


# ---- obviously-correct reference model (greedy table) ----
_TABLE = [
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
]

def ref_to_roman(n: int) -> str:
    out = []
    r = n
    for v, sym in _TABLE:
        while r >= v:
            out.append(sym)
            r -= v
    return "".join(out)


# ---- examples from spec ----
def test_example_to_roman_4():
    assert to_roman(4) == "IV"

def test_example_to_roman_1994():
    assert to_roman(1994) == "MCMXCIV"

def test_example_to_roman_3999():
    assert to_roman(3999) == "MMMCMXCIX"

def test_example_from_roman_58():
    assert from_roman("LVIII") == 58

def test_example_from_roman_IIII_raises():
    with pytest.raises(ValueError):
        from_roman("IIII")

def test_example_to_roman_0_raises():
    with pytest.raises(ValueError):
        to_roman(0)


# ---- to_roman range ----
@pytest.mark.parametrize("n", [0, -1, -100, 4000, 4001, 5000, 10000])
def test_to_roman_out_of_range_raises_valueerror(n):
    with pytest.raises(ValueError):
        to_roman(n)

@pytest.mark.parametrize("n", [1, 2, 3, 4, 5, 9, 40, 90, 400, 900, 3999])
def test_to_roman_boundaries_match_reference(n):
    assert to_roman(n) == ref_to_roman(n)

def test_to_roman_1_and_3999():
    assert to_roman(1) == "I"
    assert to_roman(3999) == "MMMCMXCIX"


# ---- to_roman types ----
@pytest.mark.parametrize("bad", [True, False, 1.0, 4.0, "IV", "4", None, [4], (4,), 4.5])
def test_to_roman_wrong_type_raises_typeerror(bad):
    with pytest.raises(TypeError):
        to_roman(bad)


# ---- from_roman types ----
@pytest.mark.parametrize("bad", [True, False, None, 1, 58, 4.0, b"IV", ["I"], ("I",)])
def test_from_roman_wrong_type_raises_typeerror(bad):
    with pytest.raises(TypeError):
        from_roman(bad)


# ---- from_roman rejects ----
def test_from_roman_empty_raises():
    with pytest.raises(ValueError):
        from_roman("")

@pytest.mark.parametrize("s", ["iv", "Iv", "iV", "mcmxciv", "lviii"])
def test_from_roman_lowercase_raises(s):
    with pytest.raises(ValueError):
        from_roman(s)

@pytest.mark.parametrize("s", [" X", "X ", "X\n", "\tX", "X\n", "M CM", "M\tM"])
def test_from_roman_whitespace_raises(s):
    with pytest.raises(ValueError):
        from_roman(s)

@pytest.mark.parametrize("s", ["IIII", "VV", "XXXX", "LL", "CCCC", "DD", "MMMM",
                               "IIV", "IC", "XM", "IL", "IM", "XD", "IXI", "IVI",
                               "VIV", "IXIV", "MCMXCIVM", "MCXIM"])
def test_from_roman_noncanonical_raises(s):
    with pytest.raises(ValueError):
        from_roman(s)

@pytest.mark.parametrize("s", ["", "A", "Z", "IIA", "M*", "123", "IVXQ", "-I"])
def test_from_roman_unknown_chars_raise(s):
    if s == "":
        pytest.skip("covered elsewhere")
    with pytest.raises(ValueError):
        from_roman(s)

def test_from_roman_MMMM_raises():
    with pytest.raises(ValueError):
        from_roman("MMMM")


# ---- targeted defect: trailing M / concatenated numerals accepted ----
def test_from_roman_rejects_trailing_M_after_full_numeral():
    # "MCMXCIV" is 1994; appending "M" is not canonical for any n.
    # Buggy code returns 2994 instead of raising.
    assert to_roman(1994) == "MCMXCIV"
    assert to_roman(2994) == "MMCMXCIV"
    with pytest.raises(ValueError):
        from_roman("MCMXCIVM")

def test_from_roman_rejects_minimal_trailing_M():
    # "MCXI" is 1111, "MCXIM" must be invalid.
    assert to_roman(1111) == "MCXI"
    with pytest.raises(ValueError):
        from_roman("MCXIM")

def test_from_roman_rejects_concatenated_numerals():
    # Two canonical blocks concatenated is never canonical.
    with pytest.raises(ValueError):
        from_roman("MCXIMCXI")

def test_from_roman_rejects_repeated_full_block():
    with pytest.raises(ValueError):
        from_roman("MCMXCIVMCMXCIV")


# ---- invariants / properties ----
@given(st.integers(min_value=1, max_value=3999))
def test_property_roundtrip_to_then_from(n):
    assert from_roman(to_roman(n)) == n

@given(st.integers(min_value=1, max_value=3999))
def test_property_to_roman_matches_reference(n):
    assert to_roman(n) == ref_to_roman(n)

@given(st.integers(min_value=1, max_value=3999))
def test_property_to_roman_result_is_canonical(n):
    s = to_roman(n)
    assert isinstance(s, str)
    assert 1 <= len(s) <= 15
    assert re.fullmatch(r"M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})", s)
    assert s == s.upper()
    assert from_roman(s) == n

@given(st.integers(min_value=1, max_value=3999))
def test_property_from_roman_result_in_range(n):
    v = from_roman(to_roman(n))
    assert isinstance(v, int) and not isinstance(v, bool)
    assert 1 <= v <= 3999

@given(st.text(alphabet="IVXLCDM", min_size=1, max_size=9))
def test_property_from_roman_accepts_only_canonical(s):
    # Strict inverse: if from_roman accepts s, then to_roman of result must equal s.
    try:
        v = from_roman(s)
    except ValueError:
        return
    assert isinstance(v, int) and not isinstance(v, bool)
    assert 1 <= v <= 3999
    assert to_roman(v) == s

@given(st.text(alphabet="IVXLCDM \n\tivxlcdmAZ09", min_size=0, max_size=8))
def test_property_from_roman_fuzz_never_crashes_and_respects_inverse(s):
    try:
        v = from_roman(s)
    except ValueError:
        return
    except TypeError:
        pytest.fail("from_roman raised TypeError on a str input")
    assert 1 <= v <= 3999
    assert to_roman(v) == s

def test_property_exhaustive_spot_check_canonical_set():
    # every canonical string round-trips: to_roman(from_roman(s)) == s
    for n in list(range(1, 100)) + [400, 500, 900, 1000, 1994, 2994, 3999]:
        s = ref_to_roman(n)
        assert from_roman(s) == n
        assert to_roman(from_roman(s)) == s
